-- CyberGuard AI - InfinityFree / shared host full reset (tables + detection seed).
-- DROP DATABASE is disabled on shared hosts, so this drops and recreates the TABLES instead.
-- WARNING: deletes the old tables and ALL their data.
-- Steps: create the database in the host panel, open phpMyAdmin, CLICK that database in the
-- left list, then Import this file. Do not use cyberguard_db_xampp.sql there.

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS `scan_summaries`;
DROP TABLE IF EXISTS `community_reports`;
DROP TABLE IF EXISTS `threat_indicators`;
DROP TABLE IF EXISTS `detection_rules`;
DROP TABLE IF EXISTS `detection_sources`;
DROP TABLE IF EXISTS `reports`;
DROP TABLE IF EXISTS `scans`;
DROP TABLE IF EXISTS `rate_limits`;
DROP TABLE IF EXISTS `users`;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE `scans` (
  `scan_id`        INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `input_type`     VARCHAR(50)  NOT NULL DEFAULT 'text',
  `classification` VARCHAR(50)  NOT NULL,
  `risk_score`     TINYINT UNSIGNED NOT NULL,
  `input_length`   INT UNSIGNED NOT NULL DEFAULT 0,
  `detector_version` VARCHAR(40) NULL,
  `evidence_json` TEXT NULL,
  `created_at`     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`scan_id`),
  KEY `idx_scans_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- reports: auto-generated scan summaries (source='scan') and user threat reports (source='user')
CREATE TABLE `reports` (
  `report_id`   INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `scan_id`     INT UNSIGNED DEFAULT NULL,
  `source`      ENUM('scan','user') NOT NULL DEFAULT 'scan',
  `category`    VARCHAR(100) NOT NULL,
  `description` TEXT         NOT NULL,
  `created_at`  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`report_id`),
  KEY `idx_reports_scan_id` (`scan_id`),
  KEY `idx_reports_created_at` (`created_at`),
  CONSTRAINT `fk_reports_scan` FOREIGN KEY (`scan_id`) REFERENCES `scans` (`scan_id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- rate_limits: per-IP request counters (replaces the easily-bypassed session counters)
CREATE TABLE `rate_limits` (
  `ip`           VARCHAR(45)  NOT NULL,
  `bucket`       VARCHAR(50)  NOT NULL,
  `window_start` INT UNSIGNED NOT NULL,
  `hits`         INT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (`ip`, `bucket`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE detection_sources (
  source_id VARCHAR(50) NOT NULL PRIMARY KEY,
  publisher VARCHAR(100) NOT NULL,
  title VARCHAR(255) NOT NULL,
  url VARCHAR(1000) NOT NULL,
  reviewed_on DATE NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE detection_rules (
  rule_id VARCHAR(60) NOT NULL PRIMARY KEY,
  dataset_version VARCHAR(40) NOT NULL,
  rule_json TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE threat_indicators (
  url_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  source_id VARCHAR(50) NOT NULL,
  imported_at DATETIME NOT NULL,
  expires_at DATETIME NOT NULL,
  PRIMARY KEY (url_hash,source_id),
  INDEX indicators_expiry (expires_at),
  CONSTRAINT indicator_source FOREIGN KEY (source_id) REFERENCES detection_sources(source_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Next import data/detection_seed.sql.

CREATE TABLE community_reports (
  report_id INT UNSIGNED NOT NULL PRIMARY KEY,
  submitted_url VARCHAR(2048) NULL,
  url_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
  status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',
  review_note VARCHAR(1000) NOT NULL DEFAULT '',
  reviewed_at DATETIME NULL,
  expires_at DATETIME NULL,
  INDEX community_lookup (url_hash,status,expires_at),
  CONSTRAINT community_report_fk FOREIGN KEY (report_id) REFERENCES reports(report_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- scan_summaries: one stored summary per scan (id, result, recommendation, cited detection sources).
CREATE TABLE scan_summaries (
  summary_id     INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  scan_id        INT UNSIGNED NOT NULL,
  report_id      INT UNSIGNED NULL,
  classification VARCHAR(50)  NOT NULL,
  risk_score     TINYINT UNSIGNED NOT NULL,
  recommendation VARCHAR(255) NOT NULL,
  source_ids     VARCHAR(255) NOT NULL DEFAULT '',
  created_at     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_summary_scan (scan_id),
  KEY idx_summary_created (created_at),
  CONSTRAINT fk_summary_scan   FOREIGN KEY (scan_id)   REFERENCES scans(scan_id)     ON DELETE CASCADE,
  CONSTRAINT fk_summary_report FOREIGN KEY (report_id) REFERENCES reports(report_id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

